// ===== rtl/cru_rotate.v =====
// Central rotational unit (CRU): y = x * exp(-j q pi/512) with a constant-coefficient rotator.
//
// Bit-exact with btpsd.cordic.rotate_fixed:
//   1. octant reduction   quad = q[9:8]; r = q[7:0]; if r > 128 { quad += 1; r = 256 - r }
//   2. ROM (a, b, inv)    for r = 0..128 (cru_rom.v, generated)
//   3. rotation           yr = xr a +/- xi b,  yi = xi a -/+ xr b   (+/-: clockwise / counter-clockwise)
//   4. gain correction    z = round(y * inv / 2^14)   (one rounding, half up, or floor if ROUND = 0)
//   5. quadrant           multiply by (-j)^quad: swap / negate, then saturate to WL bits
//
// Four register stages (LAT_CRU = 4): [octant, ROM] [rotation] [gain, shift] [quadrant, saturate].
// A new input may be presented every cycle.

module cru_rotate #(
    parameter WL    = 16,
    parameter ROUND = 1
) (
    input                      clk,
    input  signed [WL-1:0]     xr,
    input  signed [WL-1:0]     xi,
    input         [9:0]        q,
    output signed [WL-1:0]     yr,
    output signed [WL-1:0]     yi
);
    localparam signed [WL+12:0] MAXV = (1 <<< (WL - 1)) - 1;
    localparam signed [WL+12:0] MINV = -(1 <<< (WL - 1));
    localparam integer          RND_ADD = ROUND ? 8192 : 0;   // 2^(14-1)

    // ---- stage 0 (combinational): octant reduction and ROM ------------------------
    wire        flip   = (q[7:0] > 8'd128);
    wire [1:0]  quad_c = q[9:8] + {1'b0, flip};
    wire [7:0]  r_c    = flip ? (9'd256 - {1'b0, q[7:0]}) : q[7:0];
    wire [7:0]  a_c, b_c;
    wire [14:0] inv_c;
    cru_rom u_rom (.r(r_c), .a(a_c), .b(b_c), .inv(inv_c));

    // ---- stage 1 register ----------------------------------------------------------
    reg signed [WL-1:0] x1r, x1i;
    reg        [7:0]    a1, b1;
    reg        [14:0]   inv1;
    reg        [1:0]    quad1;
    reg                 ccw1;
    always @(posedge clk) begin
        x1r <= xr;  x1i <= xi;
        a1 <= a_c;  b1 <= b_c;  inv1 <= inv_c;
        quad1 <= quad_c;  ccw1 <= flip;
    end

    // ---- stage 2: rotation by the integer pair (a, b) ------------------------------
    wire signed [8:0]    sa = {1'b0, a1};
    wire signed [8:0]    sb = {1'b0, b1};
    wire signed [WL+8:0] p_ra = x1r * sa;
    wire signed [WL+8:0] p_ia = x1i * sa;
    wire signed [WL+8:0] p_rb = x1r * sb;
    wire signed [WL+8:0] p_ib = x1i * sb;
    wire signed [WL+9:0] yr_c = ccw1 ? (p_ra - p_ib) : (p_ra + p_ib);
    wire signed [WL+9:0] yi_c = ccw1 ? (p_ia + p_rb) : (p_ia - p_rb);

    reg signed [WL+9:0] y2r, y2i;
    reg        [14:0]   inv2;
    reg        [1:0]    quad2;
    always @(posedge clk) begin
        y2r <= yr_c;  y2i <= yi_c;
        inv2 <= inv1;  quad2 <= quad1;
    end

    // ---- stage 3: gain correction y * inv / 2^14 -----------------------------------
    wire signed [15:0]   sinv = {1'b0, inv2};
    wire signed [WL+25:0] g_r = y2r * sinv;
    wire signed [WL+25:0] g_i = y2i * sinv;
    wire signed [WL+25:0] h_r = g_r + RND_ADD;
    wire signed [WL+25:0] h_i = g_i + RND_ADD;

    reg signed [WL+11:0] z3r, z3i;
    reg        [1:0]     quad3;
    always @(posedge clk) begin
        z3r <= h_r >>> 14;
        z3i <= h_i >>> 14;
        quad3 <= quad2;
    end

    // ---- stage 4: quadrant (-j)^quad, saturation -----------------------------------
    reg signed [WL+12:0] o_r, o_i;
    always @* begin
        case (quad3)
            2'd0:    begin o_r = z3r;   o_i = z3i;   end
            2'd1:    begin o_r = z3i;   o_i = -z3r;  end
            2'd2:    begin o_r = -z3r;  o_i = -z3i;  end
            default: begin o_r = -z3i;  o_i = z3r;   end
        endcase
    end

    function signed [WL-1:0] sat;
        input signed [WL+12:0] v;
        begin
            if (v > MAXV)      sat = MAXV[WL-1:0];
            else if (v < MINV) sat = MINV[WL-1:0];
            else               sat = v[WL-1:0];
        end
    endfunction

    reg signed [WL-1:0] y4r, y4i;
    always @(posedge clk) begin
        y4r <= sat(o_r);
        y4i <= sat(o_i);
    end
    assign yr = y4r;
    assign yi = y4i;
endmodule

// ===== rtl/r8_butterfly.v =====
// Radix-8 butterfly: scaled (1/8) 8-point DFT followed by the output twiddle rotations.
//
// Bit-exact with  btpsd.r8fft.dft8_fixed  followed by  btpsd.cordic.rotate_fixed  (output k rotated by tq[k]):
//   stage 1  distance 4: s_i = (x_i + x_{i+4}) >> 1,  d_i = (x_i - x_{i+4}) >> 1,  d_i *= W8^i (CRU, q = 0, 128, 256, 384)
//   stage 2  distance 2: c0 = g0 + g2, c2 = g0 - g2, c1 = g1 + g3, c3 = (-j)(g1 - g3)          (each result >> 1)
//   stage 3  distance 1: out[slot] = c0 + c1, out[slot+4] = c0 - c1, out[slot+2] = c2 + c3, ... (each result >> 1)
//   twiddle  Y[k] *= exp(-j tq[k] pi/512), k = 1..7 (CRU); Y[0] is passed through.
// Every add/subtract is followed by one rounded right shift and clamped to WL bits (only the rounded difference of the
// two extreme codes can exceed the range, by one LSB); the (-j) negation saturates.
//
// Ports are packed buses: slot m of x/y at bits [m*WL +: WL]; twiddle slot k = 1..7 at tq[(k-1)*10 +: 10].
// tq is presented together with x.  Latency LAT_BFLY = 1 + LAT_CRU + 1 + LAT_CRU = 10 cycles; one butterfly per cycle.

module r8_butterfly #(
    parameter WL    = 16,
    parameter ROUND = 1
) (
    input                  clk,
    input  [8*WL-1:0]      xr,
    input  [8*WL-1:0]      xi,
    input  [69:0]          tq,
    output [8*WL-1:0]      yr,
    output [8*WL-1:0]      yi
);
    localparam LC = 4;

    // ---- arithmetic helpers --------------------------------------------------------
    // Clamp a (WL+2)-bit two's-complement value to WL bits: it fits exactly when its top three bits agree.
    function signed [WL-1:0] sat_wl;
        input signed [WL+1:0] t;
        begin
            if (t[WL+1] == t[WL] && t[WL] == t[WL-1]) sat_wl = t[WL-1:0];
            else if (t[WL+1])                         sat_wl = {1'b1, {(WL-1){1'b0}}};
            else                                      sat_wl = {1'b0, {(WL-1){1'b1}}};
        end
    endfunction

    // (a + b) >> 1 and (a - b) >> 1 with rounding, clamped to WL bits.  The clamp only matters for the difference
    // of the two extreme codes: (2^(WL-1) - 1) - (-2^(WL-1)) + 1 halves to +2^(WL-1), one above the largest code.
    function signed [WL-1:0] hadd;
        input signed [WL-1:0] a;
        input signed [WL-1:0] b;
        reg signed [WL+1:0] t;
        begin
            t = a + b;
            if (ROUND) t = t + 1;
            t = t >>> 1;
            hadd = sat_wl(t);
        end
    endfunction

    function signed [WL-1:0] hsub;
        input signed [WL-1:0] a;
        input signed [WL-1:0] b;
        reg signed [WL+1:0] t;
        begin
            t = a - b;
            if (ROUND) t = t + 1;
            t = t >>> 1;
            hsub = sat_wl(t);
        end
    endfunction

    // -a, saturating the single overflow case a = -2^(WL-1)
    function signed [WL-1:0] nsat;
        input signed [WL-1:0] a;
        begin
            if (a == {1'b1, {(WL-1){1'b0}}}) nsat = {1'b0, {(WL-1){1'b1}}};
            else                             nsat = -a;
        end
    endfunction

    integer i;

    // ---- stage 1: distance-4 add/subtract -------------------------------------------
    reg [4*WL-1:0] s1r, s1i, d1r, d1i;
    always @(posedge clk) begin
        for (i = 0; i < 4; i = i + 1) begin
            s1r[i*WL +: WL] <= hadd(xr[i*WL +: WL], xr[(i+4)*WL +: WL]);
            s1i[i*WL +: WL] <= hadd(xi[i*WL +: WL], xi[(i+4)*WL +: WL]);
            d1r[i*WL +: WL] <= hsub(xr[i*WL +: WL], xr[(i+4)*WL +: WL]);
            d1i[i*WL +: WL] <= hsub(xi[i*WL +: WL], xi[(i+4)*WL +: WL]);
        end
    end

    // ---- W8^i on the difference branch (i = 1, 2, 3 through the CRU; i = 0 is delayed) -
    wire [WL-1:0] w1r, w1i, w2r, w2i, w3r, w3i;
    cru_rotate #(.WL(WL), .ROUND(ROUND)) u_w1 (.clk(clk), .xr(d1r[1*WL +: WL]), .xi(d1i[1*WL +: WL]), .q(10'd128), .yr(w1r), .yi(w1i));
    cru_rotate #(.WL(WL), .ROUND(ROUND)) u_w2 (.clk(clk), .xr(d1r[2*WL +: WL]), .xi(d1i[2*WL +: WL]), .q(10'd256), .yr(w2r), .yi(w2i));
    cru_rotate #(.WL(WL), .ROUND(ROUND)) u_w3 (.clk(clk), .xr(d1r[3*WL +: WL]), .xi(d1i[3*WL +: WL]), .q(10'd384), .yr(w3r), .yi(w3i));

    wire [4*WL-1:0] s2r, s2i;
    wire [WL-1:0]   d20r, d20i;
    delay_line #(.W(10*WL), .N(LC)) u_dl_s (
        .clk(clk),
        .d({s1r, s1i, d1r[WL-1:0], d1i[WL-1:0]}),
        .q({s2r, s2i, d20r, d20i}));

    wire [4*WL-1:0] gdr = {w3r, w2r, w1r, d20r};   // rotated difference branch, slot m at m*WL
    wire [4*WL-1:0] gdi = {w3i, w2i, w1i, d20i};

    // ---- stages 2 and 3: distance-2 and distance-1 add/subtract (one register stage) ---
    reg [8*WL-1:0]  y3r, y3i;
    reg [4*WL-1:0]  gr, gi;
    reg signed [WL-1:0] c0r, c0i, c1r, c1i, c2r, c2i, c3r, c3i, e3r, e3i;
    integer grp;
    always @(posedge clk) begin
        for (grp = 0; grp < 2; grp = grp + 1) begin
            gr = grp ? gdr : s2r;
            gi = grp ? gdi : s2i;
            c0r = hadd(gr[0*WL +: WL], gr[2*WL +: WL]);
            c0i = hadd(gi[0*WL +: WL], gi[2*WL +: WL]);
            c2r = hsub(gr[0*WL +: WL], gr[2*WL +: WL]);
            c2i = hsub(gi[0*WL +: WL], gi[2*WL +: WL]);
            c1r = hadd(gr[1*WL +: WL], gr[3*WL +: WL]);
            c1i = hadd(gi[1*WL +: WL], gi[3*WL +: WL]);
            e3r = hsub(gr[1*WL +: WL], gr[3*WL +: WL]);
            e3i = hsub(gi[1*WL +: WL], gi[3*WL +: WL]);
            c3r = e3i;            // (-j)(e3r + j e3i) = e3i - j e3r
            c3i = nsat(e3r);
            y3r[(0+grp)*WL +: WL] <= hadd(c0r, c1r);
            y3i[(0+grp)*WL +: WL] <= hadd(c0i, c1i);
            y3r[(4+grp)*WL +: WL] <= hsub(c0r, c1r);
            y3i[(4+grp)*WL +: WL] <= hsub(c0i, c1i);
            y3r[(2+grp)*WL +: WL] <= hadd(c2r, c3r);
            y3i[(2+grp)*WL +: WL] <= hadd(c2i, c3i);
            y3r[(6+grp)*WL +: WL] <= hsub(c2r, c3r);
            y3i[(6+grp)*WL +: WL] <= hsub(c2i, c3i);
        end
    end

    // ---- output twiddles --------------------------------------------------------------
    wire [69:0] tqd;
    delay_line #(.W(70), .N(LC + 2)) u_dl_tq (.clk(clk), .d(tq), .q(tqd));

    delay_line #(.W(2*WL), .N(LC)) u_dl_y0 (
        .clk(clk),
        .d({y3r[WL-1:0], y3i[WL-1:0]}),
        .q({yr[WL-1:0], yi[WL-1:0]}));

    genvar k;
    generate
        for (k = 1; k < 8; k = k + 1) begin : g_tw
            cru_rotate #(.WL(WL), .ROUND(ROUND)) u_tw (
                .clk(clk),
                .xr(y3r[k*WL +: WL]), .xi(y3i[k*WL +: WL]),
                .q(tqd[(k-1)*10 +: 10]),
                .yr(yr[k*WL +: WL]),  .yi(yi[k*WL +: WL]));
        end
    endgenerate
endmodule

// ===== rtl/fft512_mem.v =====
// Memory-based 512-point FFT: in-place radix-8 DIF on eight 64-word banks, one butterfly issued per cycle.
//
// Mirrors btpsd.schedule / btpsd.r8fft (bit-exact, scaled by 1/512):
//   address a = 64 a2 + 8 a1 + a0,  bank = (a2 + a1 + a0) mod 8,  row = 8 a2 + a1
//   pass 0 / 1 / 2 combine the eight words that differ in digit a2 / a1 / a0; they always sit in eight different banks.
//   butterfly b = 8 hi + lo of pass p, slot m:  bank = (m + hi + lo) mod 8,
//       row = {m, hi} (pass 0), {hi, m} (pass 1), {hi, lo} (pass 2)
//   twiddle exponent of output k (units of pi/512): pass 0: 2 b k, pass 1: 16 lo k, pass 2: none
//   after pass 2 the word at address (a2, a1, a0) is the spectrum value X[a2 + 8 a1 + 64 a0].
//
// Interface (all synchronous to clk):
//   load    ld_en, ld_addr (natural order), ld_re, ld_im   - only while idle
//   run     start (pulse while idle) -> busy ... done (one-cycle pulse, results are in the banks)
//   unload  rd_k (natural frequency index) -> rd_re / rd_im one cycle later, only while idle
//
// Schedule: LAT = LAT_BFLY + 2 cycles from issue to the cycle in which the written word can be read again.  Pass 1 can
// start LAT - 8 cycles late at most (the producers of its first butterfly are pass-0 butterflies 0, 8, ..., 56), so
// STALL = max(0, LAT - 8) idle cycles are inserted after pass 0; there is no other hazard (btpsd.schedule.schedule_cycles).

module fft512_mem #(
    parameter WL    = 16,
    parameter ROUND = 1
) (
    input                      clk,
    input                      rst_n,
    // load (natural order)
    input                      ld_en,
    input      [8:0]           ld_addr,
    input  signed [WL-1:0]     ld_re,
    input  signed [WL-1:0]     ld_im,
    // control
    input                      start,
    output reg                 busy,
    output reg                 done,
    // unload (natural frequency order, data one cycle after rd_k)
    input      [8:0]           rd_k,
    output signed [WL-1:0]     rd_re,
    output signed [WL-1:0]     rd_im
);
    localparam LB    = 10;
    localparam LAT   = LB + 2;
    localparam STALL = (LAT > 8) ? (LAT - 8) : 0;
    localparam DW    = 2 * WL;

    localparam [1:0] ST_IDLE = 2'd0, ST_RUN = 2'd1, ST_DRAIN = 2'd2;

    reg [1:0] st;
    reg       iss_v;                  // a butterfly is issued in this cycle
    reg [1:0] iss_p;
    reg [5:0] iss_b;
    reg [3:0] stall_cnt;
    reg [4:0] drain_cnt;

    wire run_mode = (st != ST_IDLE);

    // ---- issue controller ---------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st <= ST_IDLE;  busy <= 1'b0;  done <= 1'b0;
            iss_v <= 1'b0;  iss_p <= 2'd0;  iss_b <= 6'd0;
            stall_cnt <= 4'd0;  drain_cnt <= 5'd0;
        end else begin
            done <= 1'b0;
            case (st)
                ST_IDLE: begin
                    if (start) begin
                        st <= ST_RUN;  busy <= 1'b1;
                        iss_v <= 1'b1;  iss_p <= 2'd0;  iss_b <= 6'd0;
                    end
                end
                ST_RUN: begin
                    if (stall_cnt != 4'd0) begin
                        stall_cnt <= stall_cnt - 4'd1;
                        if (stall_cnt == 4'd1) iss_v <= 1'b1;
                    end else if (iss_b == 6'd63) begin
                        if (iss_p == 2'd2) begin
                            iss_v <= 1'b0;
                            st <= ST_DRAIN;
                            drain_cnt <= LAT - 2;
                        end else begin
                            iss_p <= iss_p + 2'd1;
                            iss_b <= 6'd0;
                            if (iss_p == 2'd0 && STALL != 0) begin
                                iss_v <= 1'b0;
                                stall_cnt <= STALL;
                            end
                        end
                    end else begin
                        iss_b <= iss_b + 6'd1;
                    end
                end
                default: begin   // ST_DRAIN
                    if (drain_cnt == 5'd0) begin
                        st <= ST_IDLE;  busy <= 1'b0;  done <= 1'b1;
                    end else begin
                        drain_cnt <= drain_cnt - 5'd1;
                    end
                end
            endcase
        end
    end

    // ---- address functions -------------------------------------------------------------
    function [5:0] row_fn;
        input [1:0] p;
        input [2:0] m;
        input [2:0] hi;
        input [2:0] lo;
        begin
            case (p)
                2'd0:    row_fn = {m, hi};
                2'd1:    row_fn = {hi, m};
                default: row_fn = {hi, lo};
            endcase
        end
    endfunction

    function [9:0] twq;                      // twiddle exponent, units of pi/512
        input [1:0] p;
        input [5:0] b;
        input [2:0] k;
        reg   [9:0] t;
        begin
            case (p)
                2'd0:    t = ({4'd0, b} * {7'd0, k}) << 1;
                2'd1:    t = ({7'd0, b[2:0]} * {7'd0, k}) << 4;
                default: t = 10'd0;
            endcase
            twq = t;
        end
    endfunction

    // ---- control pipeline ---------------------------------------------------------------
    wire        v1;
    wire [1:0]  p1;
    wire [5:0]  b1;
    delay_line #(.W(9), .N(1)) u_meta1 (.clk(clk), .d({iss_v, iss_p, iss_b}), .q({v1, p1, b1}));

    wire        vw;
    wire [1:0]  pw;
    wire [5:0]  bw;
    delay_line #(.W(9), .N(LB)) u_meta2 (.clk(clk), .d({v1, p1, b1}), .q({vw, pw, bw}));

    // ---- load / unload address decode ------------------------------------------------------
    wire [2:0] ld_bank = ld_addr[8:6] + ld_addr[5:3] + ld_addr[2:0];
    wire [5:0] ld_row  = {ld_addr[8:6], ld_addr[5:3]};

    wire [2:0] ul_bank = rd_k[2:0] + rd_k[5:3] + rd_k[8:6];     // a2 = k[2:0], a1 = k[5:3], a0 = k[8:6]
    wire [5:0] ul_row  = {rd_k[2:0], rd_k[5:3]};
    reg  [2:0] ul_bank_q;
    always @(posedge clk) ul_bank_q <= ul_bank;

    // ---- banks ------------------------------------------------------------------------------
    wire [8*DW-1:0] rq_all;                  // bank j at [j*DW +: DW] = {re, im}
    wire [8*WL-1:0] bf_yr, bf_yi;

    wire [2:0] s_rd = iss_b[5:3] + iss_b[2:0];
    wire [2:0] s_wr = bw[5:3] + bw[2:0];

    genvar j;
    generate
        for (j = 0; j < 8; j = j + 1) begin : g_bank
            localparam [2:0] JB = j;
            wire [2:0]    m_r    = JB - s_rd;
            wire [5:0]    raddr  = run_mode ? row_fn(iss_p, m_r, iss_b[5:3], iss_b[2:0]) : ul_row;
            wire [2:0]    m_w    = JB - s_wr;
            wire [5:0]    wrow   = row_fn(pw, m_w, bw[5:3], bw[2:0]);
            wire [WL-1:0] wd_re  = bf_yr[m_w*WL +: WL];
            wire [WL-1:0] wd_im  = bf_yi[m_w*WL +: WL];
            wire          we     = run_mode ? vw : (ld_en && (ld_bank == JB));
            wire [5:0]    waddr  = run_mode ? wrow : ld_row;
            wire [DW-1:0] wdata  = run_mode ? {wd_re, wd_im} : {ld_re, ld_im};
            ram_1r1w #(.DW(DW), .AW(6)) u_ram (
                .clk(clk), .we(we), .waddr(waddr), .wdata(wdata),
                .raddr(raddr), .rdata(rq_all[j*DW +: DW]));
        end
    endgenerate

    // ---- butterfly input: slot m comes from bank (m + s1) mod 8 -----------------------------------
    wire [2:0] s1 = b1[5:3] + b1[2:0];
    wire [8*WL-1:0] bf_xr, bf_xi;
    wire [69:0]     bf_tq;
    genvar m;
    generate
        for (m = 0; m < 8; m = m + 1) begin : g_slot
            localparam [2:0] MB = m;
            wire [2:0]    bk = MB + s1;
            wire [DW-1:0] w  = rq_all[bk*DW +: DW];
            assign bf_xr[m*WL +: WL] = w[DW-1:WL];
            assign bf_xi[m*WL +: WL] = w[WL-1:0];
            if (m > 0) begin : g_tq
                assign bf_tq[(m-1)*10 +: 10] = twq(p1, b1, MB);
            end
        end
    endgenerate

    r8_butterfly #(.WL(WL), .ROUND(ROUND)) u_bf (
        .clk(clk), .xr(bf_xr), .xi(bf_xi), .tq(bf_tq), .yr(bf_yr), .yi(bf_yi));

    // ---- unload data --------------------------------------------------------------------------------
    wire [DW-1:0] rd_w = rq_all[ul_bank_q*DW +: DW];
    assign rd_re = rd_w[DW-1:WL];
    assign rd_im = rd_w[WL-1:0];
endmodule

// ===== rtl/mag_sq_odd.v =====
// Magnitude squared  p = re^2 + im^2  by the sum-of-odd-numbers squarer of the paper (SERIAL = 1) or by multipliers.
//
// n^2 = 1 + 3 + 5 + ... + (2|n| - 1): one adder and a down counter per operand, no multiplier.  The real and the
// imaginary squarer run in parallel, so a serial evaluation takes max(|re|, |im|) cycles (btpsd.squarer.mag_sq, units = 2)
// plus two control cycles.  With SERIAL = 0 the result is registered after one cycle.
//
//   start  pulse while !busy, with re / im stable in that cycle
//   done   one-cycle pulse, p valid from the cycle in which done is high until the next start

module mag_sq_odd #(
    parameter WL     = 16,
    parameter SERIAL = 1
) (
    input                    clk,
    input                    rst_n,
    input                    start,
    input  signed [WL-1:0]   re,
    input  signed [WL-1:0]   im,
    output reg               busy,
    output reg               done,
    output reg [2*WL-1:0]    p
);
    generate
        if (SERIAL) begin : g_serial
            reg [WL-1:0]   cnt_r, cnt_i;          // |re|, |im| remaining
            reg [2*WL-1:0] odd_r, odd_i;          // next odd number
            reg [2*WL-1:0] acc_r, acc_i;

            wire [WL-1:0] abs_r = re[WL-1] ? (~re + 1'b1) : re;    // |-2^(WL-1)| = 2^(WL-1) fits as unsigned
            wire [WL-1:0] abs_i = im[WL-1] ? (~im + 1'b1) : im;

            always @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    busy <= 1'b0;  done <= 1'b0;  p <= {2*WL{1'b0}};
                    cnt_r <= 0;  cnt_i <= 0;  odd_r <= 0;  odd_i <= 0;  acc_r <= 0;  acc_i <= 0;
                end else begin
                    done <= 1'b0;
                    if (!busy) begin
                        if (start) begin
                            busy  <= 1'b1;
                            cnt_r <= abs_r;  cnt_i <= abs_i;
                            odd_r <= 1;      odd_i <= 1;
                            acc_r <= 0;      acc_i <= 0;
                        end
                    end else begin
                        if (cnt_r == 0 && cnt_i == 0) begin
                            p <= acc_r + acc_i;
                            done <= 1'b1;
                            busy <= 1'b0;
                        end else begin
                            if (cnt_r != 0) begin
                                acc_r <= acc_r + odd_r;  odd_r <= odd_r + 2;  cnt_r <= cnt_r - 1'b1;
                            end
                            if (cnt_i != 0) begin
                                acc_i <= acc_i + odd_i;  odd_i <= odd_i + 2;  cnt_i <= cnt_i - 1'b1;
                            end
                        end
                    end
                end
            end
        end else begin : g_mult
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    busy <= 1'b0;  done <= 1'b0;  p <= {2*WL{1'b0}};
                end else begin
                    done <= start;
                    busy <= 1'b0;
                    if (start) p <= re * re + im * im;
                end
            end
        end
    endgenerate
endmodule

// ===== rtl/psd_engine.v =====
// PSD segment engine: chunk merge, frequency-domain window, magnitude squared and segment accumulation.
//
// Reference (sequential) microarchitecture of the datapath of paper Figs. 3-5, bit-exact with
// btpsd.estimator.psd_fixed.  One segment is two consecutive 512-sample chunk spectra A (older) and B (newer),
// both held in fft512_mem cores and read through their unload ports (scale 1/512).
//
//   merge   X(2m)   = sat((A(m) + B(m) + 1) >> 1)
//           X(2m+1) = sat(round(-j (-1)^m sum_i h_i (-1)^(m+d_i) D(m+d_i) / 2^(FD_FRAC+1))),   D = A - B,  d_i = -2 .. 3
//           indices wrap modulo 512; the six taps h_i are the integer constants FD_H0..FD_H5 (paper Eq. 6)
//   window  Xw(k) = sat(round(sum_d W(d) X(k-d) / 2^WIN_FRAC)),  d = -2 .. 2, indices wrap modulo 1024
//   square  P(k) = Xw_re^2 + Xw_im^2   (sum-of-odds squarer when SQ_SERIAL = 1)
//   accumulate  ACC(k) += P(k) over segments;  result(k) = round(ACC(k) / 2^avg_shift)
//
// This engine processes one bin at a time to keep the control simple (roughly 3 x 6 cycles per merge step and
// 3 x 5 cycles plus the squarer time per window bin).  It is the functional reference for a streaming version;
// the throughput of the paper (Table 9) is not claimed for it.  The FFT core is the high-throughput part.
//
//   clr    pulse while idle: zero the accumulators (1024 cycles)       go    pulse while idle: process one segment
//   busy   high while clearing or processing                           done  one-cycle pulse when finished
//   res_addr -> res_data: shifted accumulator, valid one cycle after res_addr, only while idle

module psd_engine #(
    parameter WL        = 12,
    parameter ROUND     = 1,
    parameter ACCW      = 2 * WL + 8,
    parameter SQ_SERIAL = 1,
    parameter signed [15:0] H0  = 512,
    parameter signed [15:0] H1  = (-869),
    parameter signed [15:0] H2  = 2608,
    parameter signed [15:0] H3  = 2608,
    parameter signed [15:0] H4  = (-869),
    parameter signed [15:0] H5  = 512,
    parameter signed [15:0] WM2 = 0,
    parameter signed [15:0] WM1 = (-256),
    parameter signed [15:0] W0  = 512,
    parameter signed [15:0] WP1 = (-256),
    parameter signed [15:0] WP2 = 0
) (
    input                      clk,
    input                      rst_n,
    input                      clr,
    input                      go,
    output reg                 busy,
    output reg                 done,
    // spectrum of the older chunk (A) and of the newer chunk (B), natural frequency order, data one cycle after the address
    output reg [8:0]           a_addr,
    input  signed [WL-1:0]     a_re,
    input  signed [WL-1:0]     a_im,
    output reg [8:0]           b_addr,
    input  signed [WL-1:0]     b_re,
    input  signed [WL-1:0]     b_im,
    // result read-out
    input      [4:0]           avg_shift,
    input      [9:0]           res_addr,
    output     [ACCW-1:0]      res_data
);
    localparam FD_SH  = 12 + 1;
    localparam WIN_SH = 10;
    localparam signed [WL+19:0] MAXV = (1 <<< (WL - 1)) - 1;
    localparam signed [WL+19:0] MINV = -(1 <<< (WL - 1));

    localparam [3:0] S_IDLE = 4'd0,  S_CLR = 4'd1,  M_A = 4'd2,  M_B = 4'd3,  M_C = 4'd4,  M_F = 4'd5,
                     W_A = 4'd6,  W_B = 4'd7,  W_C = 4'd8,  W_F = 4'd9,  W_G = 4'd10, W_S = 4'd11,
                     W_ACC = 4'd12, S_END = 4'd13;

    reg [3:0] st;
    reg [8:0] m;
    reg [2:0] t;
    reg [9:0] k;
    reg [9:0] cnt;
    reg [8:0] idx_q;

    // ---- memories -----------------------------------------------------------------------------
    reg                 x_we;
    reg  [9:0]          x_waddr;
    reg  [2*WL-1:0]     x_wdata;
    reg  [9:0]          x_raddr;
    wire [2*WL-1:0]     x_rdata;
    ram_1r1w #(.DW(2*WL), .AW(10)) u_xseg (
        .clk(clk), .we(x_we), .waddr(x_waddr), .wdata(x_wdata), .raddr(x_raddr), .rdata(x_rdata));

    reg                 acc_we;
    reg  [9:0]          acc_waddr;
    reg  [ACCW-1:0]     acc_wdata;
    wire [9:0]          acc_raddr = (st == S_IDLE) ? res_addr : k;
    wire [ACCW-1:0]     acc_rdata;
    ram_1r1w #(.DW(ACCW), .AW(10)) u_acc (
        .clk(clk), .we(acc_we), .waddr(acc_waddr), .wdata(acc_wdata), .raddr(acc_raddr), .rdata(acc_rdata));

    // ---- result scaling ---------------------------------------------------------------------------
    wire [ACCW-1:0] rnd_c = (ROUND && avg_shift != 5'd0) ? ({{(ACCW-1){1'b0}}, 1'b1} << (avg_shift - 5'd1)) : {ACCW{1'b0}};
    assign res_data = (acc_rdata + rnd_c) >> avg_shift;

    // ---- squarer ---------------------------------------------------------------------------------------
    reg                 sq_start;
    reg  signed [WL-1:0] sq_re, sq_im;
    wire                sq_busy, sq_done;
    wire [2*WL-1:0]     sq_p;
    mag_sq_odd #(.WL(WL), .SERIAL(SQ_SERIAL)) u_sq (
        .clk(clk), .rst_n(rst_n), .start(sq_start), .re(sq_re), .im(sq_im),
        .busy(sq_busy), .done(sq_done), .p(sq_p));

    // ---- merge arithmetic -------------------------------------------------------------------------------
    wire [8:0] idx = m + {6'd0, t} - 9'd2;                      // (m + d) mod 512, d = t - 2

    wire signed [WL:0] dre = a_re - b_re;
    wire signed [WL:0] dim = a_im - b_im;
    wire signed [WL:0] dpr = idx_q[0] ? -dre : dre;              // (-1)^idx * D
    wire signed [WL:0] dpi = idx_q[0] ? -dim : dim;

    function signed [15:0] hsel;
        input [2:0] tt;
        case (tt)
            3'd0: hsel = H0;
            3'd1: hsel = H1;
            3'd2: hsel = H2;
            3'd3: hsel = H3;
            3'd4: hsel = H4;
            default: hsel = H5;
        endcase
    endfunction

    function signed [15:0] wsel;
        input [2:0] tt;
        case (tt)
            3'd0: wsel = WM2;
            3'd1: wsel = WM1;
            3'd2: wsel = W0;
            3'd3: wsel = WP1;
            default: wsel = WP2;
        endcase
    endfunction

    wire signed [15:0]    hc  = hsel(t);
    wire signed [WL+16:0] prr = dpr * hc;
    wire signed [WL+16:0] pri = dpi * hc;

    wire signed [WL+1:0]  esr = a_re + b_re;
    wire signed [WL+1:0]  esi = a_im + b_im;
    wire signed [WL+1:0]  ehr = ROUND ? (esr + 1) : esr;
    wire signed [WL+1:0]  ehi = ROUND ? (esi + 1) : esi;
    wire signed [WL+1:0]  er2 = ehr >>> 1;
    wire signed [WL+1:0]  ei2 = ehi >>> 1;

    reg signed [WL+19:0]  facc_r, facc_i;
    wire signed [WL+19:0] ow_r = m[0] ? -facc_i : facc_i;       // -j (-1)^m acc = ((-1)^m acc_i, -(-1)^m acc_r)
    wire signed [WL+19:0] ow_i = m[0] ? facc_r : -facc_r;

    // ---- window arithmetic --------------------------------------------------------------------------------
    wire [9:0] idxw = k + 10'd2 - {7'd0, t};                    // (k - d) mod 1024, d = t - 2
    wire signed [WL-1:0]  xr_w = x_rdata[2*WL-1:WL];
    wire signed [WL-1:0]  xi_w = x_rdata[WL-1:0];
    wire signed [15:0]    wc   = wsel(t);
    wire signed [WL+15:0] pwr  = xr_w * wc;
    wire signed [WL+15:0] pwi  = xi_w * wc;
    reg signed [WL+19:0]  wacc_r, wacc_i;

    // round (half up), shift right by sh, saturate to WL bits
    function signed [WL-1:0] rsat;
        input signed [WL+19:0] v;
        input integer          sh;
        reg signed [WL+19:0]   tv;
        begin
            tv = ROUND ? (v + (1 <<< (sh - 1))) : v;
            tv = tv >>> sh;
            if (tv > MAXV)      rsat = MAXV[WL-1:0];
            else if (tv < MINV) rsat = MINV[WL-1:0];
            else                rsat = tv[WL-1:0];
        end
    endfunction

    // ---- control ---------------------------------------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st <= S_IDLE;  busy <= 1'b0;  done <= 1'b0;
            m <= 0;  t <= 0;  k <= 0;  cnt <= 0;  idx_q <= 0;
            a_addr <= 0;  b_addr <= 0;
            x_we <= 0;  x_waddr <= 0;  x_wdata <= 0;  x_raddr <= 0;
            acc_we <= 0;  acc_waddr <= 0;  acc_wdata <= 0;
            sq_start <= 0;  sq_re <= 0;  sq_im <= 0;
            facc_r <= 0;  facc_i <= 0;  wacc_r <= 0;  wacc_i <= 0;
        end else begin
            done     <= 1'b0;
            x_we     <= 1'b0;
            acc_we   <= 1'b0;
            sq_start <= 1'b0;
            case (st)
                S_IDLE: begin
                    if (clr) begin
                        st <= S_CLR;  busy <= 1'b1;  cnt <= 10'd0;
                    end else if (go) begin
                        st <= M_A;  busy <= 1'b1;
                        m <= 9'd0;  t <= 3'd0;
                        facc_r <= 0;  facc_i <= 0;
                    end
                end
                S_CLR: begin
                    acc_we <= 1'b1;  acc_waddr <= cnt;  acc_wdata <= {ACCW{1'b0}};
                    cnt <= cnt + 10'd1;
                    if (cnt == 10'd1023) st <= S_END;
                end
                // ---- merge: six taps per m -------------------------------------------------
                M_A: begin
                    a_addr <= idx;  b_addr <= idx;  idx_q <= idx;
                    st <= M_B;
                end
                M_B: st <= M_C;
                M_C: begin
                    facc_r <= facc_r + prr;
                    facc_i <= facc_i + pri;
                    if (t == 3'd2) begin                      // d = 0: A(m), B(m) are the even-bin operands
                        x_we <= 1'b1;  x_waddr <= {m, 1'b0};
                        x_wdata <= {er2[WL-1:0], ei2[WL-1:0]};
                    end
                    if (t == 3'd5) st <= M_F;
                    else begin t <= t + 3'd1;  st <= M_A; end
                end
                M_F: begin
                    x_we <= 1'b1;  x_waddr <= {m, 1'b1};
                    x_wdata <= {rsat(ow_r, FD_SH), rsat(ow_i, FD_SH)};
                    facc_r <= 0;  facc_i <= 0;  t <= 3'd0;
                    if (m == 9'd511) begin
                        k <= 10'd0;  wacc_r <= 0;  wacc_i <= 0;
                        st <= W_A;
                    end else begin
                        m <= m + 9'd1;
                        st <= M_A;
                    end
                end
                // ---- window, square, accumulate: five taps per bin -------------------------------------------
                W_A: begin
                    x_raddr <= idxw;
                    st <= W_B;
                end
                W_B: st <= W_C;
                W_C: begin
                    wacc_r <= wacc_r + pwr;
                    wacc_i <= wacc_i + pwi;
                    if (t == 3'd4) st <= W_F;
                    else begin t <= t + 3'd1;  st <= W_A; end
                end
                W_F: begin
                    sq_re <= rsat(wacc_r, WIN_SH);
                    sq_im <= rsat(wacc_i, WIN_SH);
                    wacc_r <= 0;  wacc_i <= 0;  t <= 3'd0;
                    st <= W_G;
                end
                W_G: begin
                    sq_start <= 1'b1;
                    st <= W_S;
                end
                W_S: begin
                    if (sq_done) st <= W_ACC;
                end
                W_ACC: begin
                    acc_we <= 1'b1;  acc_waddr <= k;  acc_wdata <= acc_rdata + {{(ACCW-2*WL){1'b0}}, sq_p};
                    if (k == 10'd1023) st <= S_END;
                    else begin k <= k + 10'd1;  st <= W_A; end
                end
                default: begin                                  // S_END
                    busy <= 1'b0;  done <= 1'b1;  st <= S_IDLE;
                end
            endcase
        end
    end
endmodule

// ===== rtl/bt_psd_top.v =====
// Chunk-merge PSD estimator: two memory-based FFT cores plus the segment engine.
//
// Sample stream in, accumulated power spectrum out.  Bit-exact with btpsd.estimator.psd_fixed.
//
//   1. 512 real samples (in_valid / in_data, accepted while in_ready) are loaded into core[cur],
//   2. the core transforms the chunk (scale 1/512),
//   3. from the second chunk on, the segment (older chunk in core[~cur], newer chunk in core[cur]) is merged, windowed,
//      squared and accumulated by psd_engine, then the next chunk is loaded into the core of the older chunk.
//
// After the last chunk has been accepted wait for in_ready (all segments finished), then read the 1024-bin result
// through res_addr / res_data (one cycle latency).  avg_shift = ceil(log2(number of segments)) must be set before the
// last segment finishes.  The accumulators are cleared once after reset (about 1024 cycles).
//
// Reference microarchitecture: loading, transforming and merging are not overlapped; see docs/ARCHITECTURE.md.

module bt_psd_top #(
    parameter WL        = 12,
    parameter ROUND     = 1,
    parameter SQ_SERIAL = 1,
    parameter ACCW      = 2 * WL + 8,
    parameter signed [15:0] WM2 = 0,
    parameter signed [15:0] WM1 = (-256),
    parameter signed [15:0] W0  = 512,
    parameter signed [15:0] WP1 = (-256),
    parameter signed [15:0] WP2 = 0
) (
    input                      clk,
    input                      rst_n,
    input      [4:0]           avg_shift,
    input                      in_valid,
    input  signed [WL-1:0]     in_data,
    output                     in_ready,
    output                     busy,
    input      [9:0]           res_addr,
    output     [ACCW-1:0]      res_data
);
    localparam [2:0] T_INIT = 3'd0, T_CLR = 3'd1, T_LOAD = 3'd2, T_FFT = 3'd3, T_SEG = 3'd4;

    reg [2:0] st;
    reg       cur;            // core that receives the chunk being loaded / transformed (the newer chunk of the segment)
    reg       have_prev;
    reg [8:0] ld_cnt;
    reg       c0_start, c1_start, eng_clr, eng_go;

    wire c0_busy, c0_done, c1_busy, c1_done;
    wire [8:0] c0_rd_k, c1_rd_k, eng_a_addr, eng_b_addr;
    wire signed [WL-1:0] c0_re, c0_im, c1_re, c1_im;
    wire eng_busy, eng_done;

    wire ld_now = (st == T_LOAD) && in_valid;
    assign in_ready = (st == T_LOAD);
    assign busy     = (st != T_LOAD);

    fft512_mem #(.WL(WL), .ROUND(ROUND)) u_core0 (
        .clk(clk), .rst_n(rst_n),
        .ld_en(ld_now && !cur), .ld_addr(ld_cnt), .ld_re(in_data), .ld_im({WL{1'b0}}),
        .start(c0_start), .busy(c0_busy), .done(c0_done),
        .rd_k(c0_rd_k), .rd_re(c0_re), .rd_im(c0_im));

    fft512_mem #(.WL(WL), .ROUND(ROUND)) u_core1 (
        .clk(clk), .rst_n(rst_n),
        .ld_en(ld_now && cur), .ld_addr(ld_cnt), .ld_re(in_data), .ld_im({WL{1'b0}}),
        .start(c1_start), .busy(c1_busy), .done(c1_done),
        .rd_k(c1_rd_k), .rd_re(c1_re), .rd_im(c1_im));

    // the engine reads A from the older core and B from the newer core
    assign c0_rd_k = cur ? eng_a_addr : eng_b_addr;
    assign c1_rd_k = cur ? eng_b_addr : eng_a_addr;
    wire signed [WL-1:0] a_re = cur ? c0_re : c1_re;
    wire signed [WL-1:0] a_im = cur ? c0_im : c1_im;
    wire signed [WL-1:0] b_re = cur ? c1_re : c0_re;
    wire signed [WL-1:0] b_im = cur ? c1_im : c0_im;

    psd_engine #(
        .WL(WL), .ROUND(ROUND), .ACCW(ACCW), .SQ_SERIAL(SQ_SERIAL),
        .WM2(WM2), .WM1(WM1), .W0(W0), .WP1(WP1), .WP2(WP2)
    ) u_eng (
        .clk(clk), .rst_n(rst_n), .clr(eng_clr), .go(eng_go), .busy(eng_busy), .done(eng_done),
        .a_addr(eng_a_addr), .a_re(a_re), .a_im(a_im),
        .b_addr(eng_b_addr), .b_re(b_re), .b_im(b_im),
        .avg_shift(avg_shift), .res_addr(res_addr), .res_data(res_data));

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st <= T_INIT;  cur <= 1'b0;  have_prev <= 1'b0;  ld_cnt <= 9'd0;
            c0_start <= 1'b0;  c1_start <= 1'b0;  eng_clr <= 1'b0;  eng_go <= 1'b0;
        end else begin
            c0_start <= 1'b0;  c1_start <= 1'b0;  eng_clr <= 1'b0;  eng_go <= 1'b0;
            case (st)
                T_INIT: begin
                    eng_clr <= 1'b1;
                    st <= T_CLR;
                end
                T_CLR: begin
                    if (eng_done) st <= T_LOAD;
                end
                T_LOAD: begin
                    if (in_valid) begin
                        if (ld_cnt == 9'd511) begin
                            ld_cnt <= 9'd0;
                            if (cur) c1_start <= 1'b1; else c0_start <= 1'b1;
                            st <= T_FFT;
                        end else begin
                            ld_cnt <= ld_cnt + 9'd1;
                        end
                    end
                end
                T_FFT: begin
                    if (cur ? c1_done : c0_done) begin
                        if (have_prev) begin
                            eng_go <= 1'b1;
                            st <= T_SEG;
                        end else begin
                            have_prev <= 1'b1;
                            cur <= ~cur;
                            st <= T_LOAD;
                        end
                    end
                end
                default: begin   // T_SEG
                    if (eng_done) begin
                        cur <= ~cur;
                        st <= T_LOAD;
                    end
                end
            endcase
        end
    end
endmodule

// ===== modelcomposer/hdl/bt_psd_mc.v =====
// Model Composer / System Generator Black Box wrapper of the chunk-merge PSD estimator (bt_psd_top).
//
// Why a wrapper.  bt_psd_top takes its samples through a ready/valid handshake and holds the producer off for the FFT and the
// segment merge (hundreds of cycles per chunk).  A Simulink signal source cannot be held off: it emits one sample per sample
// period.  The wrapper therefore RECORDS the first NCHUNKS * 512 samples that arrive (in_valid high) in a RAM, REPLAYS them into
// bt_psd_top at the pace the core accepts them, and raises done when the accumulated power spectrum is complete.
//
//   rst --> CAPTURE --(NSAMP samples seen)--> PRIME --> REPLAY --(last sample accepted)--> DRAIN --(core idle)--> DONE
//            in_valid & ce write the RAM       1 cycle   core in_valid, core in_ready       core busy              rd_addr/rd_data
//
// A one-cycle pulse on rst (synchronous, active high) re-arms the block; the estimator core is reset together with it and clears
// its accumulators by itself (about 1 024 cycles, hidden behind the capture phase).
//
// Ports
//   clk, ce       clock and clock enable.  Single-rate use: ce is expected to be 1 in every cycle.  It qualifies in_valid only; the
//                 replay and the estimator run on every clk edge, so the block must not be used in a multi-rate design.
//   rst           synchronous reset, active high
//   in_valid      1 for every sample of the record; samples that arrive while the block is not capturing are ignored
//   in_data       sample, WL-bit two's complement (Fix_WL_(WL-1) in Simulink: -1 <= x < 1)
//   rd_addr       bin to read, 0 .. 1023 (two-sided spectrum); rd_data follows one clock later
//   busy          1 from the first captured sample until done
//   done          1 while the spectrum is complete and readable (stays until the next rst)
//   rd_data       accumulated, shifted power of bin rd_addr (ACCW = 2 WL + 8 bit, unsigned); valid while done = 1.  Scale to the
//                 Welch estimate with btpsd.estimator.hw_power_scale(WL, NCHUNKS - 1, avg_shift).
//
// The number of segments is NCHUNKS - 1 and avg_shift = ceil(log2(NCHUNKS - 1)) is computed here, so the power spectrum is the
// average over the segments exactly when NCHUNKS - 1 is a power of two and scaled by (NCHUNKS - 1) / 2^avg_shift otherwise.
//
// Bit-exact with btpsd.estimator.psd_fixed on the first NCHUNKS * 512 samples (tb/tb_bt_psd_mc.v).

module bt_psd_mc #(
    parameter WL        = 12,
    parameter ROUND     = 1,
    parameter SQ_SERIAL = 1,
    parameter NCHUNKS   = 5,
    parameter ACCW      = 2 * WL + 8,
    parameter signed [15:0] WM2 = 0,
    parameter signed [15:0] WM1 = (-256),
    parameter signed [15:0] W0  = 512,
    parameter signed [15:0] WP1 = (-256),
    parameter signed [15:0] WP2 = 0
) (
    input                      clk,
    input                      ce,
    input                      rst,
    input                      in_valid,
    input  signed [WL-1:0]     in_data,
    input      [9:0]           rd_addr,
    output                     busy,
    output                     done,
    output     [ACCW-1:0]      rd_data
);
    function integer clog2;
        input integer v;
        integer i;
        begin
            clog2 = 0;
            for (i = v - 1; i > 0; i = i >> 1) clog2 = clog2 + 1;
        end
    endfunction

    localparam integer NSAMP = NCHUNKS * 512;
    localparam integer AW    = clog2(NSAMP);
    localparam [4:0]   AVG_SHIFT = clog2(NCHUNKS - 1);

    localparam [2:0] S_CAPTURE = 3'd0, S_PRIME = 3'd1, S_REPLAY = 3'd2, S_DRAIN = 3'd3, S_DONE = 3'd4;

    reg [2:0]    state  = S_CAPTURE;
    reg [AW:0]   wr_cnt = 0;                 // samples captured
    reg [AW:0]   rp     = 0;                 // replay pointer: index of the sample presented to the core
    reg [WL-1:0] ram [0:NSAMP-1];
    reg [WL-1:0] rdata;

    // ---- reset of the estimator core: low from one cycle after rst until three cycles after rst falls ----------------------
    reg [3:0] rst_sr = 4'b0000;
    always @(posedge clk) rst_sr <= {rst_sr[2:0], ~rst};
    wire core_rst_n = &rst_sr;

    // ---- capture ---------------------------------------------------------------------------------------------------------------
    wire cap = (state == S_CAPTURE) && ce && in_valid;
    always @(posedge clk) if (cap) ram[wr_cnt[AW-1:0]] <= in_data;

    // ---- replay: synchronous read, the word presented in a cycle is ram[rp] ----------------------------------------------------
    wire         core_in_valid = (state == S_REPLAY);
    wire         core_in_ready, core_busy;
    wire         accept  = core_in_valid && core_in_ready;
    wire [AW:0]  rp_next = accept ? rp + 1'b1 : rp;
    wire [AW-1:0] ra     = (rp_next >= NSAMP) ? {AW{1'b0}} : rp_next[AW-1:0];
    always @(posedge clk) rdata <= ram[ra];

    always @(posedge clk) begin
        if (rst) begin
            state <= S_CAPTURE;  wr_cnt <= 0;  rp <= 0;
        end else begin
            rp <= rp_next;
            case (state)
                S_CAPTURE: if (cap) begin
                    wr_cnt <= wr_cnt + 1'b1;
                    if (wr_cnt == NSAMP - 1) state <= S_PRIME;
                end
                S_PRIME:   state <= S_REPLAY;
                S_REPLAY:  if (accept && rp == NSAMP - 1) state <= S_DRAIN;
                S_DRAIN:   if (!core_busy) state <= S_DONE;      // busy is already 1 in the first cycle after the last sample
                default:   state <= S_DONE;
            endcase
        end
    end

    assign busy = (state == S_CAPTURE) ? (wr_cnt != 0) : (state != S_DONE);
    assign done = (state == S_DONE);

    bt_psd_top #(
        .WL(WL), .ROUND(ROUND), .SQ_SERIAL(SQ_SERIAL), .ACCW(ACCW),
        .WM2(WM2), .WM1(WM1), .W0(W0), .WP1(WP1), .WP2(WP2)
    ) u_core (
        .clk(clk), .rst_n(core_rst_n), .avg_shift(AVG_SHIFT),
        .in_valid(core_in_valid), .in_data(rdata), .in_ready(core_in_ready), .busy(core_busy),
        .res_addr(rd_addr), .res_data(rd_data)
    );
endmodule
